import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import axios from "axios";

const Post = () => {
  const { id } = useParams();
  const [postObject, setPostObject] = useState({});
  const [comments, setComments] = useState([]);
  const [newComment, setNewComment] = useState("");

  useEffect(() => {
    axios.get(`http://localhost:3003/posts/byid/${id}`).then((response) => {
      setPostObject(response.data);
    });

    axios.get(`http://localhost:3003/comments/${id}`).then((response) => {
      setComments(response.data);
    });
  }, [id]); // تم إضافة id كـ dependency

  const addComment = () => {
    if (!newComment.trim()) { // تم إضافة التحقق من أن التعليق غير فارغ
      alert("Please enter a comment");
      return;
    }

    const token = sessionStorage.getItem("accesstoken");
    if (!token) { // تم إضافة التحقق من وجود توكن
      alert("You must be logged in to comment");
      return;
    }

    axios
      .post(
        "http://localhost:3003/comments",
        {
          commentbody: newComment,
          postid: id,
        },
        {
          headers: {
            accesstoken: token,
          },
        }
      )
      .then((response) => {
        if (response.data.error) {
          alert(response.data.error); // تم تغيير console.log إلى alert للمستخدم
        } else {
          const commentToAdd = { 
            commentbody: newComment,
            // تم إضافة id مؤقت للتعليق الجديد لضمان عرضه فوراً
          };
          setComments([...comments, commentToAdd]);
          setNewComment("");
        }
      })
      .catch((error) => { // تم إضافة معالجة الأخطاء
        console.error("Error adding comment:", error);
        alert("Failed to add comment. Please try again.");
      });
  };

  return (
    <div className="postPage">
      <div className="leftSide">
        <div className="post" id="individual">
          <div className="title">{postObject.title}</div>
          <div className="body">{postObject.postText}</div>
          <div className="footer">{postObject.username}</div>
        </div>
      </div>
      <div className="rightSide">
        <div className="addCommentContainer">
          <input
            type="text"
            placeholder="Comment........"
            value={newComment}
            autoComplete="off"
            onChange={(event) => {
              setNewComment(event.target.value);
            }}
            onKeyPress={(event) => { // تم إضافة إمكانية الإرسال بالضغط على Enter
              if (event.key === "Enter") {
                addComment();
              }
            }}
          />
          <button onClick={addComment}>Add Comment</button> {/* تم تصحيح الكتابة */}
        </div>
        <div className="listOfComments">
          {comments.map((comment, key) => {
            return (
              <div key={key} className="comment">
                {comment.commentbody}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default Post;
